package messagepack

import "fmt"

// streamCheckingWriter validates generated bytes and can reject a payload prefix.
type streamCheckingWriter struct {
	bytes      uint64
	writes     int
	maxRequest int
	first      chan struct{}
	failAfter  uint64
	failure    error
}

func (w *streamCheckingWriter) Write(src []byte) (n int, err error) {
	w.writes++
	if len(src) > w.maxRequest {
		w.maxRequest = len(src)
	}
	n = len(src)
	if w.failure != nil && uint64(n) > w.failAfter-w.bytes {
		n = int(w.failAfter - w.bytes)
		err = w.failure
	}
	for index, value := range src[:n] {
		if value != byte(w.bytes+uint64(index)) {
			return 0, fmt.Errorf("example: invalid generated byte at %d", w.bytes+uint64(index))
		}
	}
	w.bytes += uint64(n)
	if w.writes == 1 && w.first != nil {
		close(w.first)
	}
	return n, err
}
